mapper.select:
SELECT `id` as id, `node_id` as nodeId, `node_type` as nodeType, `created_time` as createTime , `status` as status , `gather_site` as gatherSite, `stack` as stack , `site_type` as siteType , `site_id` as siteId , `site_x` as siteX, `site_y` as siteY , `site_z` as siteZ, `into_stack_time` as intoStackTime , `site_route` as siteRoute , `maintain_stage_id` as maintainStageId FROM tb_node
and node_id like concat('%', #{nodeDto.nodeId}, '%')
and node_type = #{nodeDto.nodeType}
and site_id = #{nodeDto.siteId}
and status = #{nodeDto.status}
and into_stack_time >= #{nodeDto.startTime}
and into_stack_time <= #{nodeDto.endTime}

SELECT count(1)
FROM tb_node
WHERE node_id = #{nodeId}

